<script>
  import worldPath from './world-path.json';
  import { onMount, tick } from 'svelte';
  import ActivitySparkline from './ActivitySparkline.svelte';
  import ThreadProjection from './ThreadProjection.svelte';
  import EntityProjection from './EntityProjection.svelte';
  export let repository;
  export let error='';
  export let stale=false;
  export let refresh;
  export let openNote;
  export let openCanonical;
  export let settings;
  const blank=()=>({search:'',from:'',to:'',threadId:'',entityId:'',locationId:'',status:'',priority:'',claimState:''});
  let scope=blank();
  let page='threads', detailId='', inspectorId='', eventId='', localContext=null;
  let inspectorProjection='Time';
  let saved='Recently Changed', sort='change', group='date', density='normal', mapMode='events';
  let timeRange='All';
  let graphPreset='Thread relationships', graphLayout='radial', maxNodes=80, depth=1, selectedNode='', selectedEdge=null, hidden=new Set(), pinned=new Set(), pinnedPositions=new Map(), expanded=new Set();
  let graphNodeTypes=new Set(['thread','event','entity','location']);
  let graphEdgeTypes=new Set();
  let searchInput;
  let appRoot;
  onMount(()=>appRoot?.focus());
  let searchFocused=false;
  let history=[{page:'threads',id:'',eventId:'',scrollTop:0}], historyIndex=0, sequence='';
  let showFilters=false, showInspector=false;
  let zoom=1, selectedLocation='', selectedCluster=[];
  let entityKind='', minimumActivity=0;
  let timelineLimit=300;
  let threadEventLimit=100, expandedEvents=new Set();
  let graphRefresh=0;
  const navs=['threads','timeline','entities','map','graph'];
  const labels={threads:'Threads',timeline:'Timeline',entities:'Entities',map:'Map',graph:'Graph'};
  const reasons={contested_or_corrected_claim:'存在争议或修正的 Claim',high_priority_open_questions:'高优先级未解问题',high_priority_stale:'高优先级 Thread 多轮静默'};
  const stateGlyph={supported:'✓',uncertain:'△',analytical:'△',contested:'⇄',corrected:'↺',superseded:'↺',retracted:'⊘'};
  function rememberScroll(){if(history[historyIndex])history[historyIndex].scrollTop=appRoot?.querySelector('.wh-content')?.scrollTop||0}
  function restoreScroll(value){tick().then(()=>{const pane=appRoot?.querySelector('.wh-content');if(pane)pane.scrollTop=value||0})}
  function navigate(next,id='',extra={}){rememberScroll();if(next==='thread'&&page==='threads')threadProjection=inspectorProjection==='Time'?'Timeline':inspectorProjection;page=next;detailId=id;localContext=extra.localContext||null;inspectorId='';eventId=extra.eventId||'';if(eventId)expandedEvents=new Set([...expandedEvents,eventId]);threadEventLimit=100;showInspector=false;history=history.slice(0,historyIndex+1);history.push({page:next,id,eventId,localContext,scrollTop:0});historyIndex=history.length-1;}
  function back(){if(historyIndex>0){rememberScroll();historyIndex--;const h=history[historyIndex];page=h.page;detailId=h.id;eventId=h.eventId;localContext=h.localContext||null;restoreScroll(h.scrollTop)}}
  function forward(){if(historyIndex<history.length-1){rememberScroll();historyIndex++;const h=history[historyIndex];page=h.page;detailId=h.id;eventId=h.eventId;localContext=h.localContext||null;restoreScroll(h.scrollTop)}}
  function setScope(key,value){scope={...scope,[key]:value};}
  function setTimeRange(value){timeRange=value;if(value==='Custom'){showFilters=true;return}const days={'7d':7,'30d':30,'90d':90,'1y':365}[value];scope={...scope,from:days?new Date(Date.now()-(days-1)*86400000).toISOString().slice(0,10):'',to:''};timelineLimit=300}
  function timeNumber(value){return value?Date.parse(value)||0:0}
  function clearScope(){scope=blank();saved='Recently Changed';timeRange='All'}
  function applySaved(name){saved=name;scope={...scope,status:'',priority:''};if(name==='Active')setScope('status','active');if(name==='Watching')setScope('status','watching');if(name==='Dormant')setScope('status','dormant');if(name==='Resolved')setScope('status','resolved')}
  function sortedThreads(list){let result=[...list];if(saved==='Attention')result=result.filter(t=>t.attention.required);if(saved==='Open Questions')result=result.filter(t=>t.open_question_count);if(saved==='Stale')result=result.filter(t=>t.stale);const priority={high:0,normal:1,low:2};return result.sort((a,b)=>sort==='title'?a.title.localeCompare(b.title):sort==='priority'?priority[a.priority]-priority[b.priority]||a.title.localeCompare(b.title):sort==='tracking'?timeNumber(a.tracking_since)-timeNumber(b.tracking_since):sort==='attention'?Number(b.attention.required)-Number(a.attention.required)||timeNumber(b.last_meaningful_change_at)-timeNumber(a.last_meaningful_change_at):timeNumber(b.last_meaningful_change_at)-timeNumber(a.last_meaningful_change_at))}
  function dateOf(e){return (e.occurred_at||e.reported_at||e.first_observed_at||'未知')}
  function dateLabel(e){return e.occurred_at?`${e.occurred_at} · ${e.time_precision}`:`${dateOf(e)} · 发生时间未知（按报道/观察排序）`}
  function openRef(ref){if(ref?.obsidian_path)openNote(ref.obsidian_path)}
  function threadName(id){return repository?.threadById.get(id)?.title||id}
  function entityName(id){return repository?.entityById.get(id)?.name||id}
  function openEvent(e){navigate('thread',e.thread_ids[0]||'',{eventId:e.event_id})}
  function openSearchHit(hit){searchFocused=false;scope={...scope,search:''};if(hit.type==='thread')navigate('thread',hit.id);else if(hit.type==='event')openEvent(repository.eventById.get(hit.id));else navigate('entity',hit.id)}
  function inspectEvent(id){inspectorId=id;showInspector=true}
  function toggleEventDetail(id,open){const next=new Set(expandedEvents);open?next.add(id):next.delete(id);expandedEvents=next}
  function keyboard(event){
    if(!appRoot?.contains(document.activeElement))return;
    if(event.target instanceof HTMLInputElement||event.target instanceof HTMLSelectElement||event.target instanceof HTMLTextAreaElement)return;
    if(event.key==='/'){event.preventDefault();searchInput?.focus();return}
    if(event.key==='Escape'){if(showInspector){showInspector=false;inspectorId=''}else if(['thread','entity'].includes(page))back();return}
    if(event.key==='r'){refresh();return}
    if(event.key==='g'){sequence='g';setTimeout(()=>sequence='',900);return}
    if(sequence==='g'){const dest={t:'threads',l:'timeline',e:'entities',m:'map',g:'graph'}[event.key];sequence='';if(dest){navigate(dest);return}}
    if(event.key==='j'||event.key==='ArrowDown'||event.key==='k'||event.key==='ArrowUp'){
      const items=page==='threads'?sortedThreads(repository.filteredThreads(scope)).map(t=>t.thread_id):page==='timeline'?repository.filteredEvents(scope).map(e=>e.event_id):page==='entities'?repository.filteredEntities(scope).map(e=>e.entity_id):[];
      if(!items.length)return;event.preventDefault();let idx=items.indexOf(inspectorId);idx=Math.max(0,Math.min(items.length-1,idx+(event.key==='j'||event.key==='ArrowDown'?1:-1)));inspectorId=items[idx];showInspector=true;
    }
    if(event.key==='Enter'&&inspectorId){if(page==='threads')navigate('thread',inspectorId);else if(page==='timeline')openEvent(repository.eventById.get(inspectorId));else if(page==='entities')navigate('entity',inspectorId)}
  }
  function scopedGraph(_scope,_depth,_maxNodes,_selectedNode,_nodeTypes,_edgeTypes,_hidden,_expanded,_refresh,_preset,_localContext){
    if(repository.graphFault)return {nodes:[],edges:[]};
    const scopedEvents=repository.filteredEvents(scope);
    const eventIds=new Set(scopedEvents.map(e=>e.event_id));
    const threadIds=new Set(repository.filteredThreads(scope).map(t=>t.thread_id));
    const entityIds=new Set(repository.filteredEntities(scope).map(e=>e.entity_id));
    const allowed=new Set([...threadIds].map(id=>'thread:'+id));
    for(const id of eventIds)allowed.add('event:'+id);
    for(const id of entityIds)allowed.add('entity:'+id);
    for(const location of repository.locations)if(location.event_ids.some(id=>eventIds.has(id)))allowed.add('location:'+location.location_id);
    const evidence=graphPreset==='Evidence chain'||graphPreset==='Full scoped graph';
    if(evidence&&selectedNode){const node=repository.graphNode(selectedNode);if(node?.type==='claim'&&eventIds.has(node.owner_event_id)||node?.type==='question'&&threadIds.has(node.owner_thread_id)||node?.type==='source'&&repository.neighbors(selectedNode).some(edge=>eventIds.has(repository.graphNode(edge.source)?.owner_event_id)))allowed.add(selectedNode)}
    const allows=edge=>graphPreset==='Full scoped graph'||graphPreset==='Thread relationships'?(graphPreset==='Full scoped graph'||edge.source.startsWith('thread:')||edge.target.startsWith('thread:')):graphPreset==='Entity network'?(edge.source.startsWith('entity:')||edge.target.startsWith('entity:')):graphPreset==='Event–Entity network'?(['event:','entity:'].some(prefix=>edge.source.startsWith(prefix))&&['event:','entity:'].some(prefix=>edge.target.startsWith(prefix))):['event_contains_claim','claim_supported_by_source','thread_contains_event'].includes(edge.type);
    const admissible=(id,edge,from)=>allowed.has(id)||(evidence&&(
      id.startsWith('claim:')&&edge.type==='event_contains_claim'&&from.startsWith('event:')||
      id.startsWith('question:')&&edge.type==='question_about_thread'&&from.startsWith('thread:')||
      id.startsWith('source:')&&edge.type==='claim_supported_by_source'&&from.startsWith('claim:')));
    let seeds=[];
    if(selectedNode)seeds=[selectedNode];
    else if(localContext)seeds=[localContext.type+':'+localContext.id];
    else if(scope.threadId)seeds=['thread:'+scope.threadId];
    else if(scope.entityId)seeds=['entity:'+scope.entityId];
    else if(graphPreset==='Entity network')seeds=[...entityIds].slice(0,8).map(id=>'entity:'+id);
    else if(graphPreset==='Event–Entity network')seeds=[...eventIds].slice(0,8).map(id=>'event:'+id);
    else if(graphPreset==='Evidence chain')seeds=scopedEvents.slice(0,1).map(event=>'event:'+event.event_id);
    else seeds=[...threadIds].slice(0,8).map(id=>'thread:'+id);
    if(localContext)allowed.add(localContext.type+':'+localContext.id);
    const cap=Math.max(5,Math.min(150,Number(maxNodes)||45));
    const selected=new Set(seeds.filter(id=>repository.graphNode(id)&&allowed.has(id)&&!hidden.has(id)));
    const edgeMap=new Map();
    let frontier=[...selected];
    for(let level=0;level<depth&&frontier.length&&selected.size<cap;level++){
      const next=[];
      for(const from of frontier)for(const edge of repository.neighbors(from)){
        if(!allows(edge)||graphEdgeTypes.size&&!graphEdgeTypes.has(edge.type))continue;
        const candidate=edge.source===from?edge.target:edge.source;
        if(!admissible(candidate,edge,from)||hidden.has(candidate))continue;
        const node=repository.graphNode(candidate);
        if(!node||!graphNodeTypes.has(node.type))continue;
        edgeMap.set(edge.id,edge);
        if(!selected.has(candidate)&&selected.size<cap){selected.add(candidate);next.push(candidate)}
      }
      frontier=next;
    }
    for(const from of expanded)if(selected.has(from))for(const edge of repository.neighbors(from)){
      if(!allows(edge))continue;const candidate=edge.source===from?edge.target:edge.source;
      if(!admissible(candidate,edge,from)||hidden.has(candidate))continue;
      const node=repository.graphNode(candidate);
      if(node&&graphNodeTypes.has(node.type)&&selected.size<cap){selected.add(candidate);edgeMap.set(edge.id,edge)}
    }
    const nodes=[...selected].map(id=>({id,...repository.graphNode(id)}));
    const edges=[...edgeMap.values()].filter(edge=>selected.has(edge.source)&&selected.has(edge.target)).slice(0,300);
    if(repository.graphFault)return {nodes:[],edges:[]};
    return {nodes,edges};
  }
  function layoutPositions(slice,mode,pins){
    const nodes=slice.nodes, edges=slice.edges, result=new Map();
    if(mode==='hierarchical'){
      const rank={thread:0,event:1,entity:1,location:1,question:2,claim:2,source:3};
      const columns=[[],[],[],[]];for(const node of nodes)columns[rank[node.type]??1].push(node);
      columns.forEach((column,x)=>column.forEach((node,i)=>result.set(node.id,{x:80+x*175,y:60+(i+1)*390/(column.length+1)})));
    }else{
      nodes.forEach((node,i)=>{const angle=2*Math.PI*i/Math.max(nodes.length,1)-Math.PI/2;result.set(node.id,{x:350+Math.cos(angle)*Math.min(255,80+nodes.length*2.5),y:250+Math.sin(angle)*Math.min(185,70+nodes.length*1.8)})});
      for(const [id,position] of pins)if(result.has(id))result.set(id,{...position});
      if(mode==='force')for(let step=0;step<45;step++){
        const shifts=new Map(nodes.map(node=>[node.id,{x:0,y:0}]));
        for(let i=0;i<nodes.length;i++)for(let j=i+1;j<nodes.length;j++){
          const a=result.get(nodes[i].id),b=result.get(nodes[j].id),dx=a.x-b.x||0.1,dy=a.y-b.y||0.1,d2=Math.max(100,dx*dx+dy*dy),force=900/d2;
          shifts.get(nodes[i].id).x+=dx*force;shifts.get(nodes[i].id).y+=dy*force;
          shifts.get(nodes[j].id).x-=dx*force;shifts.get(nodes[j].id).y-=dy*force;
        }
        for(const edge of edges){const a=result.get(edge.source),b=result.get(edge.target);if(!a||!b)continue;const dx=b.x-a.x,dy=b.y-a.y;shifts.get(edge.source).x+=dx*0.012;shifts.get(edge.source).y+=dy*0.012;shifts.get(edge.target).x-=dx*0.012;shifts.get(edge.target).y-=dy*0.012}
        for(const node of nodes){if(pins.has(node.id))continue;const p=result.get(node.id),d=shifts.get(node.id);p.x=Math.max(30,Math.min(670,p.x+d.x));p.y=Math.max(30,Math.min(470,p.y+d.y))}
      }
    }
    for(const [id,position] of pins)if(result.has(id))result.set(id,position);
    return result;
  }
  function graphPosition(i,n,id){return graphPositions.get(id)||{x:350,y:250}}
  function mapPoints(_scope,_mode){const events=repository.filteredEvents(scope);const eventIds=new Set(events.map(e=>e.event_id));return repository.locations.filter(l=>l.event_ids.some(id=>eventIds.has(id))).map(l=>{const scoped=l.event_ids.filter(id=>eventIds.has(id));const count=mapMode==='threads'?new Set(scoped.flatMap(id=>repository.eventById.get(id)?.thread_ids||[])).size:mapMode==='entities'?new Set(scoped.flatMap(id=>repository.eventById.get(id)?.entity_ids||[])).size:scoped.length;return {...l,count}});}
  function clusters(points){const cells=new Map();for(const l of points){const cell=zoom<=2&&l.country_code?`country:${l.country_code}`:zoom<=2&&l.region?`region:${l.region}`:`grid:${Math.round(l.lon/(25/zoom))}:${Math.round(l.lat/(20/zoom))}`;const group=cells.get(cell)||[];group.push(l);cells.set(cell,group)}return [...cells.values()].map(group=>({locations:group,lon:group.reduce((s,l)=>s+l.lon,0)/group.length,lat:group.reduce((s,l)=>s+l.lat,0)/group.length,count:group.reduce((s,l)=>s+l.count,0)}))}
  $: visibleThreads=repository?sortedThreads(repository.filteredThreads(scope)):[];
  $: homeThreadId=page==='threads'?(inspectorId&&visibleThreads.some(t=>t.thread_id===inspectorId)?inspectorId:visibleThreads[0]?.thread_id):'';
  $: homeThread=repository&&homeThreadId?repository.thread(homeThreadId):null;
  $: observatoryEvents=repository?repository.filteredEvents({...scope,from:[scope.from,new Date(Date.now()-7*86400000).toISOString().slice(0,10)].sort().at(-1)}):[];
  $: attentionCount=visibleThreads.filter(t=>t.attention.required).length;
  $: changedCount=visibleThreads.filter(t=>t.last_meaningful_change_at&&Date.parse(t.last_meaningful_change_at)>=Date.now()-7*86400000).length;
  $: openQuestionCount=visibleThreads.reduce((sum,t)=>sum+t.open_question_count,0);
  $: visibleEvents=repository&&['timeline','map','graph'].includes(page)?repository.filteredEvents(scope):[];
  $: visibleEntities=repository?repository.filteredEntities(scope).filter(e=>(!entityKind||e.kind===entityKind)&&e.event_count>=minimumActivity):[];
  $: currentThread=repository&&page==='thread'?repository.thread(detailId):null;
  $: currentEntity=repository&&page==='entity'?repository.entity(detailId):null;
  $: graphSlice=repository&&page==='graph'?scopedGraph(scope,depth,maxNodes,selectedNode,graphNodeTypes,graphEdgeTypes,hidden,expanded,graphRefresh,graphPreset,localContext):{nodes:[],edges:[]};
  $: graphPositions=layoutPositions(graphSlice,graphLayout,pinnedPositions);
  $: locationPoints=repository&&(page==='map'||page==='thread'&&threadProjection==='Map'||page==='entity'&&entityProjection==='Map')?mapPoints(scope,mapMode):[];
  $: markerClusters=clusters(locationPoints,zoom);
  $: scopeCount=Object.values(scope).filter(Boolean).length;
  $: inspectedEvent=repository&&inspectorId&&['timeline','thread'].includes(page)?repository.eventById.get(inspectorId):null;
  $: inspectedThread=repository&&inspectorId&&repository.threadById.has(inspectorId)?repository.thread(inspectorId):null;
  $: inspectedEntity=repository&&inspectorId&&repository.entityById.has(inspectorId)?repository.entity(inspectorId):null;
  $: searchResults=repository&&scope.search?repository.search(scope.search):[];
  function graphChooseNode(id){selectedNode=id;selectedEdge=null;inspectorId=id;showInspector=true}
  function graphChooseEdge(edge){selectedEdge=edge;selectedNode='';showInspector=true}
  function toggleType(type){const next=new Set(graphNodeTypes);next.has(type)?next.delete(type):next.add(type);graphNodeTypes=next}
  function toggleEdge(type){const next=new Set(graphEdgeTypes);next.has(type)?next.delete(type):next.add(type);graphEdgeTypes=next}
  function choosePreset(value){graphPreset=value;graphLayout=value==='Evidence chain'?'hierarchical':value==='Entity network'?'force':'radial';graphNodeTypes=new Set(value==='Evidence chain'||value==='Full scoped graph'?['thread','event','entity','location','claim','source','question']:['thread','event','entity','location']);depth=value==='Evidence chain'?3:1;selectedNode='';expanded=new Set()}
  function toggleSet(setter,value,set){const next=new Set(set);next.has(value)?next.delete(value):next.add(value);setter(next)}
  function togglePin(id){const next=new Set(pinned),positions=new Map(pinnedPositions);if(next.has(id)){next.delete(id);positions.delete(id)}else{const index=graphSlice.nodes.findIndex(node=>node.id===id);if(index<0)return;positions.set(id,graphPosition(index,graphSlice.nodes.length));next.add(id)}pinned=next;pinnedPositions=positions}
  function hideNode(id){hidden=new Set([...hidden,id]);selectedNode='';showInspector=false}
  function filterLocation(id){setScope('locationId',id);navigate('timeline')}
  function mapPick(group){selectedCluster=group.locations.map(l=>l.location_id);selectedLocation=group.locations[0].location_id;showInspector=true}
  function locationEvents(id){const set=new Set(repository.locationById.get(id)?.event_ids||[]);return repository.filteredEvents(scope).filter(e=>set.has(e.event_id))}
  function focusGraph(id){selectedNode=id;graphRefresh++;navigate('graph');showInspector=true}
  function showEventMap(e){if(!e.location_ids?.length)return;selectedLocation=e.location_ids[0];selectedCluster=[selectedLocation];navigate('map');showInspector=true}
  function openGraphNode(id){const [type,object]=id.split(':');const node=repository.graphNode(id);if(type==='thread')navigate('thread',object);else if(type==='entity')navigate('entity',object);else if(type==='event')openEvent(repository.eventById.get(object));else if(type==='location')filterLocation(object);else if(type==='claim'&&node?.owner_event_id)openEvent(repository.eventById.get(node?.owner_event_id));else if(type==='question'&&node?.owner_thread_id)navigate('thread',node?.owner_thread_id);else if(type==='source'&&/^https?:\/\//.test(node?.url||''))window.open(node?.url,'_blank','noopener,noreferrer')}
  function formatDate(value){return value?value.slice(0,16).replace('T',' '):'—'}
  function groupedEvents(){const groups=new Map();for(const e of visibleEvents.slice(0,timelineLimit)){const keys=group==='thread'?e.thread_ids.map(threadName):group==='entity'?e.entity_ids.map(entityName):[dateOf(e).slice(0,10)];for(const key of keys.length?keys:['未关联']){if(!groups.has(key))groups.set(key,[]);groups.get(key).push(e)}}return [...groups.entries()]}
  function currentProjectionEvents(){return currentThread?(currentThread.event_summaries||[]).filter(e=>repository.matchesEvent(e,scope)):[]}
  let threadProjection='Overview', entityProjection='Overview';
</script>

<svelte:window on:keydown={keyboard}/>
<div class="wh-app" bind:this={appRoot} tabindex="-1">
  <header class="wh-header"><div class="wh-brand"><strong>World Historian</strong><span>Dashboard</span></div><nav aria-label="主导航">{#each navs as nav}<button class:active={page===nav||page==='thread'&&nav==='threads'||page==='entity'&&nav==='entities'} on:click={()=>navigate(nav)}>{labels[nav]}</button>{/each}</nav><div class="wh-header-actions"><button title="后退" disabled={historyIndex<=0} on:click={back}>←</button><button title="前进" disabled={historyIndex>=history.length-1} on:click={forward}>→</button><button title="刷新读模型" on:click={refresh}>↻</button><button title="设置" on:click={settings}>⚙</button></div></header>
  <div class="wh-toolbar"><div class="wh-search"><input bind:this={searchInput} type="search" placeholder="搜索 Thread、Event、Entity  /" value={scope.search} on:focus={()=>searchFocused=true} on:blur={()=>searchFocused=false} on:input={e=>setScope('search',e.currentTarget.value)}/>{#if searchFocused&&searchResults.length}<div class="wh-search-results">{#each searchResults as hit}<button on:mousedown|preventDefault={()=>openSearchHit(hit)}><span class="wh-badge">{hit.type}</span><strong>{hit.label}</strong><small>{hit.summary.slice(0,90)}</small></button>{/each}</div>{/if}</div><button on:click={()=>showFilters=!showFilters}>筛选 {scopeCount?`(${scopeCount})`:''}</button><span class="wh-scope">{scope.threadId?threadName(scope.threadId):'全局语料'}{scope.entityId?` · ${entityName(scope.entityId)}`:''}{scope.locationId?` · ${repository?.locationById.get(scope.locationId)?.name||scope.locationId}`:''}{scope.from?` · ${scope.from}→${scope.to||'现在'}`:''}{scope.status?` · ${scope.status}`:''}{scope.priority?` · ${scope.priority}`:''}</span><button on:click={clearScope} disabled={!scopeCount}>清除范围</button><small>{repository?.manifest.generated_at?`生成 ${formatDate(repository.manifest.generated_at)}`:''}</small></div>
  {#if showFilters}<div class="wh-filters"><label>起始 <input type="date" value={scope.from} on:change={e=>{timeRange='Custom';setScope('from',e.currentTarget.value)}}/></label><label>结束 <input type="date" value={scope.to} on:change={e=>{timeRange='Custom';setScope('to',e.currentTarget.value)}}/></label><label>状态 <select value={scope.status} on:change={e=>setScope('status',e.currentTarget.value)}><option value="">全部</option>{#each ['active','watching','dormant','resolved','archived'] as s}<option value={s}>{s}</option>{/each}</select></label><label>优先级 <select value={scope.priority} on:change={e=>setScope('priority',e.currentTarget.value)}><option value="">全部</option>{#each ['high','normal','low'] as p}<option value={p}>{p}</option>{/each}</select></label><label>Thread <select value={scope.threadId} on:change={e=>setScope('threadId',e.currentTarget.value)}><option value="">全部</option>{#each repository?.threads||[] as t}<option value={t.thread_id}>{t.title}</option>{/each}</select></label><label>Entity <select value={scope.entityId} on:change={e=>setScope('entityId',e.currentTarget.value)}><option value="">全部</option>{#each repository?.entities||[] as e}<option value={e.entity_id}>{e.name}</option>{/each}</select></label><label>Location <select value={scope.locationId} on:change={e=>setScope('locationId',e.currentTarget.value)}><option value="">全部</option>{#each repository?.locations||[] as l}<option value={l.location_id}>{l.name}</option>{/each}</select></label><label>Claim <select value={scope.claimState} on:change={e=>setScope('claimState',e.currentTarget.value)}><option value="">全部</option>{#each ['supported','uncertain','contested','superseded'] as s}<option value={s}>{s}</option>{/each}</select></label></div>{/if}
  {#if error}<div class="wh-alert">读模型不可用：{error}<button on:click={refresh}>构建读模型</button><button on:click={settings}>设置路径</button></div>{:else if repository}
  {#if repository.warning}<div class="wh-alert wh-warning">{repository.warning}<button on:click={refresh}>重新构建</button></div>{/if}
  {#if stale}<div class="wh-alert wh-warning">Chronicle 数据比当前读模型更新。<button on:click={refresh}>刷新</button></div>{/if}
  <main class="wh-main">
  {#if page==='threads'}
    <aside class="wh-sidebar"><h3>Saved Views</h3>{#each ['Attention','Active','Watching','Dormant','Resolved','Open Questions','Stale','Recently Changed'] as view}<button class:active={saved===view} on:click={()=>applySaved(view)}>{view}{#if view==='Attention'} <span>{repository.threads.filter(t=>t.attention.required).length}</span>{/if}</button>{/each}<p>{visibleThreads.length} Threads</p></aside>
    <section class="wh-content wh-observatory">
      <div class="wh-observatory-strip" aria-label="最近 7 天的历史动向"><div><small>Needs Attention</small><strong>{attentionCount}</strong><span>需要核查的 Thread</span></div><div><small>Events · 7d</small><strong>{observatoryEvents.length}</strong><span>按 Event 时间统计</span></div><div><small>Changed Threads · 7d</small><strong>{changedCount}</strong><span>最近有意义变更</span></div><div><small>Open Questions</small><strong>{openQuestionCount}</strong><span>当前范围内未解</span></div></div>
      <div class="wh-section-bar"><h2>Threads in Motion <small>{visibleThreads.length}</small></h2><label>排序 <select bind:value={sort}><option value="attention">需关注</option><option value="change">最近有意义变更</option><option value="priority">优先级</option><option value="title">标题</option><option value="tracking">跟踪开始</option></select></label></div>
      {#if !visibleThreads.length}<div class="wh-empty">当前范围没有 Thread。<button on:click={clearScope}>清除筛选</button></div>{/if}
      {#each visibleThreads as thread}<div class="wh-row wh-motion-row" role="button" tabindex="0" on:keydown={e=>e.key==='Enter'&&(inspectorId=thread.thread_id)} class:selected={homeThreadId===thread.thread_id} on:click={()=>{inspectorId=thread.thread_id;showInspector=true}} on:dblclick={()=>navigate('thread',thread.thread_id)}>
        <div class="wh-row-head"><strong>{thread.title}</strong><span class="wh-badge">{thread.status}</span><span class="wh-badge">{thread.priority}</span></div>
        <p>{thread.latest_event_summary||'尚无 Event'}</p>
        <div class="wh-motion-signals"><ActivitySparkline series={thread.activity_series}/><span class="wh-change-markers" aria-label="状态变化">{#if thread.recent_change_types?.includes('claim_corrected')}<span title="Claim 已修正">↺ 修正</span>{/if}{#if thread.recent_change_types?.includes('claim_contested')}<span title="Claim 有争议">⇄ 争议</span>{/if}{#if thread.recent_change_types?.includes('claim_retracted')}<span title="Claim 已撤回">⊘ 撤回</span>{/if}{#if thread.open_question_count}<span title="未解问题">○ {thread.open_question_count} 问题</span>{/if}</span></div>
        {#if thread.attention.required}<div class="wh-attention">{thread.attention.reasons.map(r=>reasons[r]||r).join('；')}</div>{/if}
        <small>{formatDate(thread.last_meaningful_change_at)} · {thread.top_entity_ids.slice(0,3).map(entityName).join(' · ')}</small>
      </div>{/each}
    </section>
  {:else if page==='thread'&&currentThread}
    <section class="wh-content wh-detail"><div class="wh-section-bar"><div><button on:click={back}>← 返回</button><h2>{currentThread.title}</h2><span class="wh-badge">{currentThread.status}</span><span class="wh-badge">{currentThread.priority}</span></div><div><button disabled={!currentThread.canonical_ref.obsidian_path} on:click={()=>openRef(currentThread.canonical_ref)}>打开源笔记</button><button on:click={()=>openCanonical(currentThread.canonical_ref)}>查看 Chronicle 记录</button></div></div><div class="wh-meta">跟踪自 {formatDate(currentThread.tracking_since)} · 最近有意义变更 {formatDate(currentThread.last_meaningful_change_at)} · Chronicle ID {currentThread.thread_id}</div><div class="wh-tabs">{#each ['Overview','Timeline','Map','Graph'] as projection}<button class:active={threadProjection===projection} on:click={()=>threadProjection=projection}>{projection}</button>{/each}</div>
      {#if threadProjection==='Overview'}<section class="wh-card"><h3>Current State</h3>{#if currentThread.current_state?.text}<p>{currentThread.current_state.text}</p><small>{currentThread.current_state.provenance} · {formatDate(currentThread.current_state.updated_at)}{currentThread.current_state.revision?` · ${currentThread.current_state.revision}`:''}</small>{#if currentThread.current_state.source_refs?.length}<div class="wh-chips">审计引用：{#each currentThread.current_state.source_refs as ref}<button on:click={()=>repository.eventById.has(ref)?openEvent(repository.eventById.get(ref)):null}>{ref}</button>{/each}</div>{/if}{#if currentThread.current_state.canonical_ref}<button class="wh-event-link" on:click={()=>openCanonical(currentThread.current_state.canonical_ref)}>查看综合记录</button>{/if}{#if currentThread.current_state.stale}<div class="wh-attention">新 Event 晚于当前状态综合。</div>{/if}{:else}<p class="wh-muted">Chronicle 尚无 Current State 记录。</p>{/if}</section>{#if currentThread.annotations?.length}<section class="wh-card"><h3>Manual annotations</h3>{#each currentThread.annotations as annotation}<p class="wh-annotation">{annotation.text}</p><small>人工批注 · <button on:click={()=>openNote(annotation.canonical_ref.path)}>打开源笔记</button></small>{/each}</section>{/if}<section class="wh-card"><h3>Event activity</h3><ActivitySparkline series={currentThread.activity_series} width={300} height={64}/><p class="wh-muted">最近 12 周，以最新 Event 所在周为终点；按发生日期、每周计数。</p></section><section class="wh-card"><h3>Open Questions <span>{currentThread.open_questions?.filter(q=>q.state==='open').length||0}</span></h3>{#each currentThread.open_questions?.filter(q=>q.state==='open')||[] as q}<div class="wh-subrow"><strong>{q.question}</strong><small>{q.state} · {formatDate(q.opened_at)} · 更新 {formatDate(q.last_updated_at)} <button class="wh-canonical-link" on:click={()=>openCanonical(q.canonical_ref)}>查看记录</button></small></div>{:else}<p class="wh-muted">没有未解问题。</p>{/each}<details><summary>已回答及其他问题</summary>{#each currentThread.open_questions?.filter(q=>q.state!=='open')||[] as q}<div class="wh-subrow">{q.question} · {q.state}{#if q.answer_event_id&&repository.eventById.has(q.answer_event_id)}<button class="wh-event-link" on:click={()=>openEvent(repository.eventById.get(q.answer_event_id))}>查看回答 Event</button>{/if}</div>{/each}</details></section><section class="wh-card"><h3>Entities</h3><div class="wh-chips">{#each currentThread.entity_ids||[] as id}<button on:click={()=>navigate('entity',id)}>{entityName(id)}</button>{/each}</div></section><section class="wh-card"><h3>Related Threads</h3>{#each currentThread.related_threads||[] as rel}<div class="wh-subrow"><button on:click={()=>navigate('thread',rel.thread_id)}>{threadName(rel.thread_id)}</button><small>{rel.type}</small></div>{:else}<p class="wh-muted">没有显式关联。</p>{/each}</section><section class="wh-card"><h3>Recent Events</h3>{#each currentProjectionEvents().slice(0,8) as e}<button class="wh-event-link" on:click={()=>{threadProjection='Timeline';eventId=e.event_id}}>{dateLabel(e)} · {e.title}</button>{/each}</section>
      {:else if threadProjection==='Timeline'}{#each currentProjectionEvents().slice(0,threadEventLimit) as e}<div class="wh-event-card" class:highlight={eventId===e.event_id}><span class="wh-detail-time-node" class:approximate={e.time_precision!=='day'} title={dateLabel(e)}></span><div><button class="wh-title-link" on:click={()=>inspectEvent(e.event_id)}>{e.title}</button><small>{dateLabel(e)} · {e.claim_count} Claims · {e.source_count} Sources</small></div><p>{e.summary}</p><details open={eventId===e.event_id} on:toggle={ev=>toggleEventDetail(e.event_id,ev.currentTarget.open)}><summary>证据与元数据</summary><div class="wh-event-meta">发生 {e.occurred_at||'未知'}（{e.time_precision}） · 报道 {e.reported_at||'—'} · 首次观察 {e.first_observed_at||'—'} · 置信度 {e.confidence} · 状态 {e.state}</div><div class="wh-chips">{#each e.entity_ids as id}<button on:click={()=>navigate('entity',id)}>{entityName(id)}</button>{/each}{#each e.location_ids as id}<button on:click={()=>filterLocation(id)}>{repository.locationById.get(id)?.name||id}</button>{/each}</div><small>Chronicle: {e.event_id}</small><button class="wh-event-link" on:click={()=>openCanonical(e.canonical_ref)}>查看 Chronicle 记录</button>{#if e.canonical_ref.obsidian_path}<button class="wh-event-link" on:click={()=>openRef(e.canonical_ref)}>打开源笔记</button>{/if}{#if expandedEvents.has(e.event_id)}{#each repository.event(e.event_id).claims||[] as claim}<div class="wh-claim"><strong>{stateGlyph[claim.state]||'△'} {claim.state}</strong> {claim.statement}{#if claim.superseded_by}<small>被 Claim {claim.superseded_by} 取代</small>{/if}<button class="wh-canonical-link" on:click={()=>openCanonical(claim.canonical_ref)}>Claim 记录</button><small>{claim.source?.publisher||'来源未知'} · {claim.source?.title||'来源缺失'} · {claim.source?.source_kind||'unknown'} · {claim.source?.published_at||'日期未知'} · {claim.source?.relationship||'来源'} {#if claim.source}<button class="wh-canonical-link" on:click={()=>openCanonical(claim.source.canonical_ref)}>Source 记录</button>{/if} {#if claim.source?.url}<a href={claim.source.url} target="_blank" rel="noopener noreferrer">打开来源 ↗</a>{/if}</small></div>{/each}{/if}</details></div>{:else}<div class="wh-empty">当前范围没有 Event。<button on:click={clearScope}>清除筛选</button></div>{/each}{#if currentProjectionEvents().length>threadEventLimit}<button class="wh-load-more" on:click={()=>threadEventLimit+=100}>再加载 100 个 Event</button>{/if}
      {:else if threadProjection==='Map'}{@const localPoints=locationPoints.filter(l=>l.thread_ids.includes(currentThread.thread_id))}<div class="wh-card"><h3>Thread Map</h3><ThreadProjection thread={currentThread} {repository} projection="Map" openLocation={id=>{setScope('locationId',id);navigate('map')}}/>{#if localPoints.length}<div class="wh-location-list">{#each localPoints as l}<button on:click={()=>{selectedLocation=l.location_id;selectedCluster=[l.location_id];showInspector=true}}>{l.name} · {l.geo_precision} · {l.count} Events</button>{/each}</div>{:else}<div class="wh-empty">此 Thread 没有带明确坐标的 Event 地点。</div>{/if}</div>
      {:else}<div class="wh-card"><h3>Thread Graph</h3><ThreadProjection thread={currentThread} {repository} projection="Graph" openEntity={id=>navigate('entity',id)}/><button on:click={()=>{navigate('graph','',{localContext:{type:'thread',id:currentThread.thread_id}})}}>打开交互图谱 →</button><p class="wh-muted">以当前 Thread 为中心，逐步展开关系。</p></div>{/if}
    </section>
  {:else if page==='timeline'}
    <section class="wh-content wh-wide"><div class="wh-section-bar"><h2>Timeline <small>{visibleEvents.length} Events</small></h2><div><div class="wh-range-switch" aria-label="Timeline 时间范围">{#each ['7d','30d','90d','1y','All','Custom'] as range}<button class:active={timeRange===range} on:click={()=>setTimeRange(range)}>{range}</button>{/each}</div><label>分组 <select bind:value={group}><option value="date">日期</option><option value="thread">Thread</option><option value="entity">Entity</option></select></label><label>密度 <select bind:value={density}><option value="normal">标准</option><option value="compact">紧凑</option></select></label></div></div>{#if !visibleEvents.length}<div class="wh-empty">当前范围没有 Event。<button on:click={clearScope}>清除筛选</button></div>{/if}{#each groupedEvents() as [name,items]}<h3 class="wh-group">{name} <span class="wh-density-bar" style={`width:${Math.min(100,Math.sqrt(items.length)*12)}px`} title={`${items.length} Events`}></span><small>{items.length} Events</small></h3>{#each items as e}<div class="wh-timeline-row" role="button" tabindex="0" on:keydown={ev=>ev.key==='Enter'&&!ev.target.closest('.wh-timeline-expanded')&&inspectEvent(e.event_id)} class:compact={density==='compact'} on:click={ev=>!ev.target.closest('.wh-timeline-expanded')&&inspectEvent(e.event_id)}><div class="wh-time"><span class:approximate={e.time_precision!=='day'} class="wh-time-node"></span>{dateLabel(e)}</div><div><strong>{e.title}</strong><small>{e.thread_ids.map(threadName).join(' · ')}</small>{#if density!=='compact'}<p>{e.summary}</p>{/if}<small>{e.entity_ids.slice(0,4).map(entityName).join(' · ')} · {e.claim_count} Claims · {e.source_count} Sources</small></div><button on:click|stopPropagation={()=>openEvent(e)}>打开 →</button>{#if inspectorId===e.event_id}{@const detail=repository.event(e.event_id)}<div class="wh-timeline-expanded">
  <div class="wh-event-meta">发生 {e.occurred_at||'未知'}（{e.time_precision}） · 报道 {e.reported_at||'—'} · 首次观察 {e.first_observed_at||'—'} · 状态 {e.state}</div>
  <p>{e.summary}</p><div class="wh-chips">{#each e.entity_ids as id}<button on:click={()=>navigate('entity',id)}>{entityName(id)}</button>{/each}{#each e.location_ids as id}<button on:click={()=>{selectedLocation=id;selectedCluster=[id];navigate('map');showInspector=true}}>{repository.locationById.get(id)?.name||id}</button>{/each}</div>
  {#each detail.claims||[] as claim}<div class="wh-claim"><strong>{stateGlyph[claim.state]||'△'} {claim.state}</strong> {claim.statement}<small>{claim.source?.publisher||'来源未知'} · {claim.source?.title||'来源缺失'} {#if claim.source?.url}<a href={claim.source.url} target="_blank" rel="noopener noreferrer">来源 ↗</a>{/if}</small><button class="wh-canonical-link" on:click={()=>openCanonical(claim.canonical_ref)}>Claim 记录</button></div>{/each}
  <div class="wh-timeline-actions"><button on:click={()=>openCanonical(e.canonical_ref)}>Event 记录</button><button on:click={()=>focusGraph('event:'+e.event_id)}>在 Graph 高亮</button>{#if e.location_ids.length}<button on:click={()=>showEventMap(e)}>在 Map 高亮</button>{/if}</div>
</div>{/if}</div>{/each}{/each}{#if visibleEvents.length>timelineLimit}<button class="wh-load-more" on:click={()=>timelineLimit+=300}>再加载 300 条（已显示 {Math.min(timelineLimit,visibleEvents.length)} / {visibleEvents.length}）</button>{/if}</section>
  {:else if page==='entities'}
    <section class="wh-content wh-wide"><div class="wh-section-bar"><h2>Entities <small>{visibleEntities.length}</small></h2><div><label>类型 <select bind:value={entityKind}><option value="">全部</option>{#each [...new Set(repository.entities.map(e=>e.kind))].sort() as kind}<option value={kind}>{kind}</option>{/each}</select></label><label>最少 Events <input type="number" min="0" max="10000" bind:value={minimumActivity}/></label></div></div>{#if !visibleEntities.length}<div class="wh-empty">当前范围没有 Entity。<button on:click={clearScope}>清除筛选</button></div>{/if}<div class="wh-entity-grid">{#each visibleEntities.slice(0,500) as entity}<button class="wh-entity-row" on:click={()=>navigate('entity',entity.entity_id)}><strong>{entity.name}</strong><span class="wh-badge">{entity.kind}</span><span class="wh-entity-top">{entity.thread_ids.slice(0,2).map(threadName).join(' · ')}</span><small>{entity.thread_count} Threads · {entity.event_count} Events · {formatDate(entity.last_seen_at)}</small></button>{/each}</div>{#if visibleEntities.length>500}<p class="wh-muted">显示前 500 个 Entity。请使用搜索缩小范围。</p>{/if}</section>
  {:else if page==='entity'&&currentEntity}
    <section class="wh-content wh-detail"><div class="wh-section-bar"><div><button on:click={back}>← 返回</button><h2>{currentEntity.name}</h2><span class="wh-badge">{currentEntity.kind}</span></div><button on:click={()=>openCanonical(currentEntity.canonical_ref)}>查看 Chronicle 记录</button></div><div class="wh-meta">别名 {currentEntity.aliases.join('、')||'—'} · 最近出现 {formatDate(currentEntity.last_seen_at)} · Chronicle ID {currentEntity.entity_id}</div><div class="wh-tabs">{#each ['Overview','Map','Graph'] as projection}<button class:active={entityProjection===projection} on:click={()=>entityProjection=projection}>{projection}</button>{/each}</div>{#if entityProjection==='Overview'}<section class="wh-card"><h3>Current involvement</h3>{#each currentEntity.current_thread_ids||[] as id}<button class="wh-event-link" on:click={()=>navigate('thread',id)}>{threadName(id)}</button>{:else}<p class="wh-muted">没有活跃的关联 Thread。</p>{/each}</section><section class="wh-card"><h3>Threads</h3>{#each currentEntity.thread_ids as id}<button class="wh-event-link" on:click={()=>navigate('thread',id)}>{threadName(id)}</button>{:else}<p class="wh-muted">没有关联 Thread。</p>{/each}</section><section class="wh-card"><h3>Event Activity</h3><ActivitySparkline series={currentEntity.activity_series} width={300} height={64}/><p class="wh-muted">最近 12 周，以最新 Event 所在周为终点；按发生日期、每周计数。</p>{#each currentEntity.event_ids.map(id=>repository.eventById.get(id)).filter(Boolean).slice(-50).reverse() as e}<button class="wh-event-link" on:click={()=>openEvent(e)}>{dateLabel(e)} · {e.title}</button>{/each}</section><section class="wh-card"><h3>Related Entities</h3><div class="wh-chips">{#each currentEntity.related_entity_ids||[] as id}<button on:click={()=>navigate('entity',id)}>{entityName(id)}</button>{:else}<p class="wh-muted">没有显式 Entity 关系。</p>{/each}</div></section><section class="wh-card"><h3>Thread questions (context)</h3><p class="wh-muted">以下问题属于关联 Thread，不表示问题直接关于此 Entity。</p>{#each currentEntity.contextual_questions?.filter(q=>q.state==='open')||[] as q}<div class="wh-subrow"><strong>{q.question}</strong><button on:click={()=>navigate('thread',q.owner_thread_id)}>{threadName(q.owner_thread_id)}</button></div>{:else}<p class="wh-muted">没有未解问题。</p>{/each}</section>{:else if entityProjection==='Map'}<section class="wh-card"><h3>Entity Map</h3><EntityProjection entity={currentEntity} {repository} projection="Map" openLocation={id=>{setScope('locationId',id);navigate('map')}}/>{#each currentEntity.location_ids||[] as id}<button class="wh-event-link" on:click={()=>filterLocation(id)}>{repository.locationById.get(id)?.name||id}</button>{:else}<p class="wh-muted">没有有坐标的相关 Event 地点。</p>{/each}</section>{:else}<section class="wh-card"><h3>Entity Graph</h3><EntityProjection entity={currentEntity} {repository} projection="Graph" openThread={id=>navigate('thread',id)} openEntity={id=>navigate('entity',id)}/><button on:click={()=>{navigate('graph','',{localContext:{type:'entity',id:currentEntity.entity_id}})}}>打开交互图谱 →</button></section>{/if}</section>
  {:else if page==='map'}
    <section class="wh-content wh-wide"><div class="wh-section-bar"><h2>Map <small>{locationPoints.length} Locations</small></h2><div><label>模式 <select bind:value={mapMode}><option value="events">Events</option><option value="threads">Threads</option><option value="entities">Entities</option></select></label><button on:click={()=>zoom=Math.min(8,zoom*2)}>＋</button><button on:click={()=>zoom=Math.max(1,zoom/2)}>－</button><button on:click={()=>{zoom=1}}>重置</button></div></div>{#if !locationPoints.length}<div class="wh-empty">当前范围没有已地理编码的 Event。Chronicle 快照没有 Event 地点坐标；仅接受有明确发生地证据和精度的地点。<button on:click={clearScope}>清除筛选</button></div>{:else}<div class="wh-map"><svg viewBox="0 0 900 450" role="img" aria-label="地理事件分布"><rect x="0" y="0" width="900" height="450" class="wh-map-bg"/><g transform={`translate(450,225) scale(${zoom}) translate(-450,-225)`}><path d={worldPath} class="wh-world-shape"/>{#each [-180,-120,-60,0,60,120,180] as lon}<line x1={(lon+180)*2.5} x2={(lon+180)*2.5} y1="0" y2="450" class="wh-map-grid"/>{/each}{#each [-60,-30,0,30,60] as lat}<line x1="0" x2="900" y1={(90-lat)*2.5} y2={(90-lat)*2.5} class="wh-map-grid"/>{/each}{#each markerClusters as marker}<g class="wh-map-marker" class:focused={marker.locations.some(l=>l.location_id===selectedLocation)} class:approximate={marker.locations.some(l=>!['exact','city'].includes(l.geo_precision))} role="button" tabindex="0" on:click={()=>mapPick(marker)} on:keydown={e=>e.key==='Enter'&&mapPick(marker)} transform={`translate(${(marker.lon+180)*2.5},${(90-marker.lat)*2.5}) scale(${1/zoom})`}><circle r={Math.min(26,9+Math.sqrt(marker.count)*3)}/><text text-anchor="middle" dy="4">{marker.count}</text></g>{/each}</g></svg><p class="wh-muted">经纬网与坐标来自本地读模型。圆点聚合随缩放变化；地点精度见检查器。</p></div>{/if}</section>
  {:else if page==='graph'}
    <section class="wh-content wh-wide"><div class="wh-section-bar"><h2>Graph <small>{graphSlice.nodes.length} Nodes · {graphSlice.edges.length} Edges</small></h2><div><label>预设 <select value={graphPreset} on:change={e=>choosePreset(e.currentTarget.value)}><option>Thread relationships</option><option>Entity network</option><option>Event–Entity network</option><option>Evidence chain</option><option>Full scoped graph</option></select></label><label>布局 <select bind:value={graphLayout}><option value="radial">径向</option><option value="force">静态力导向</option><option value="hierarchical">证据层级</option></select></label><label>深度 <select bind:value={depth}><option value={1}>1</option><option value={2}>2</option><option value={3}>3</option></select></label><label>节点上限 <input type="number" min="5" max="150" bind:value={maxNodes}/></label><button on:click={()=>{selectedNode='';hidden=new Set();expanded=new Set();pinned=new Set();pinnedPositions=new Map();graphRefresh++}}>重置布局</button></div></div><div class="wh-graph-controls"><span>节点</span>{#each ['thread','event','entity','location','claim','source','question'] as type}<label><input type="checkbox" checked={graphNodeTypes.has(type)} on:change={()=>toggleType(type)}/>{type}</label>{/each}<span>关系</span><select on:change={e=>e.currentTarget.value&&toggleEdge(e.currentTarget.value)}><option value="">选择关系类型</option>{#each repository.graphEdgeTypes() as type}<option value={type}>{graphEdgeTypes.has(type)?'✓ ':''}{type}</option>{/each}</select>{#if graphEdgeTypes.size}<button on:click={()=>graphEdgeTypes=new Set()}>清除关系过滤</button>{/if}<input type="search" placeholder="搜索节点" on:change={e=>{const term=e.currentTarget.value.toLocaleLowerCase();const match=graphSlice.nodes.find(n=>n.label.toLocaleLowerCase().includes(term));if(match)graphChooseNode(match.id)}}/></div>{#if !graphSlice.nodes.length}<div class="wh-empty">{#if repository.graphFault}图索引无效：{repository.graphFault} <button on:click={refresh}>重建读模型</button>{:else}当前范围没有关系图节点。<button on:click={clearScope}>清除筛选</button>{/if}</div>{:else}<div class="wh-graph"><svg viewBox="0 0 700 500" role="img" aria-label="类型化关系图">{#each graphSlice.edges as edge}{@const a=graphSlice.nodes.findIndex(n=>n.id===edge.source)}{@const b=graphSlice.nodes.findIndex(n=>n.id===edge.target)}<line x1={graphPosition(a,graphSlice.nodes.length,edge.source).x} y1={graphPosition(a,graphSlice.nodes.length,edge.source).y} x2={graphPosition(b,graphSlice.nodes.length,edge.target).x} y2={graphPosition(b,graphSlice.nodes.length,edge.target).y} class="wh-graph-edge" role="button" tabindex="0" on:keydown={ev=>ev.key==='Enter'&&graphChooseEdge(edge)} on:click={()=>graphChooseEdge(edge)}><title>{edge.type}</title></line>{/each}{#each graphSlice.nodes as node,i}<g transform={`translate(${graphPosition(i,graphSlice.nodes.length,node.id).x},${graphPosition(i,graphSlice.nodes.length,node.id).y})`} class="wh-graph-node" class:focused={selectedNode===node.id} role="button" tabindex="0" on:click={()=>graphChooseNode(node.id)} on:keydown={e=>e.key==='Enter'&&graphChooseNode(node.id)}>{#if node.type==='thread'}<rect x="-15" y="-10" width="30" height="20" rx="6" class="wh-node-thread"/>{:else if node.type==='claim'||node.type==='location'}<polygon points={node.type==='claim'?'0,-11 11,0 0,11 -11,0':'0,-12 10,0 0,12 -10,0'} class:wh-node-claim={node.type==='claim'} class:wh-node-location={node.type==='location'}/>{:else if node.type==='source'}<rect x="-8" y="-10" width="16" height="20" class="wh-node-source"/>{:else if node.type==='question'}<circle r="9" class="wh-node-question"/>{:else}<circle r={node.type==='entity'?10:7} class:entity={node.type==='entity'} class:event={node.type==='event'}/>{/if}{#if graphSlice.nodes.length<=25||node.type==='thread'||node.id===selectedNode}<text y="-17" text-anchor="middle">{node.label.slice(0,18)}</text>{/if}<title>{node.type}: {node.label}</title></g>{/each}</svg></div>{/if}</section>
  {/if}
  {#if showInspector||page==='threads'}<aside class="wh-inspector" class:wh-home-inspector={page==='threads'} class:wh-inspector-open={showInspector}><button class="wh-close" on:click={()=>showInspector=false}>×</button>{#if selectedEdge&&page==='graph'}<h3>{selectedEdge.type}</h3><p>方向：{selectedEdge.source} → {selectedEdge.target}</p><p>置信度：{selectedEdge.confidence??'未提供'}</p><p>证据引用：{JSON.stringify(selectedEdge.evidence_refs||[])}</p>{:else if selectedNode&&page==='graph'}{@const node=repository.graphNode(selectedNode)}<h3>{node?.label||selectedNode}</h3><p>{node?.type}{node?.state?` · ${node.state}`:''}{node?.publisher?` · ${node.publisher}`:''}</p>{#if node?.confidence!=null}<p>置信度：{node.confidence}</p>{/if}<p>当前图内度数：{graphSlice.edges.filter(e=>e.source===selectedNode||e.target===selectedNode).length}</p><button on:click={()=>toggleSet(v=>expanded=v,selectedNode,expanded)}>展开邻居</button><button on:click={()=>hideNode(selectedNode)}>隐藏节点</button><button on:click={()=>togglePin(selectedNode)}>{pinned.has(selectedNode)?'取消固定':'固定'}</button><button on:click={()=>openGraphNode(selectedNode)}>打开对象</button>{#if node?.type==='entity'}<button on:click={()=>{setScope('entityId',selectedNode.slice(7));navigate('timeline')}}>按 Entity 筛选 Timeline</button><button on:click={()=>{setScope('entityId',selectedNode.slice(7));navigate('threads')}}>按 Entity 筛选 Threads</button>{/if}{#if node?.canonical_ref?.kind==='chronicle'}<button on:click={()=>openCanonical(node.canonical_ref)}>查看 Chronicle 记录</button>{/if}{:else if selectedLocation&&(page==='map'||page==='thread'&&threadProjection==='Map'||page==='entity'&&entityProjection==='Map')}{@const l=repository.locationById.get(selectedLocation)}<h3>{selectedCluster.length>1?`${selectedCluster.length} 个地点`:(l?.name||selectedLocation)}</h3>{#if selectedCluster.length>1}<div class="wh-location-list">{#each selectedCluster as id}<button on:click={()=>{selectedLocation=id;selectedCluster=[id]}}>{repository.locationById.get(id)?.name||id}</button>{/each}</div>{/if}<p>精度：{l?.geo_precision} · 坐标：{l?.lat}, {l?.lon}</p><p>{locationEvents(selectedLocation).length} Events · {l?.thread_ids.length} Threads</p><p>日期：{locationEvents(selectedLocation).length?`${dateOf(locationEvents(selectedLocation).at(-1))} → ${dateOf(locationEvents(selectedLocation)[0])}`:'—'}</p><p>Entities：</p><div class="wh-chips">{#each [...new Set(locationEvents(selectedLocation).flatMap(e=>e.entity_ids))].slice(0,6) as id}<button on:click={()=>navigate('entity',id)}>{entityName(id)}</button>{:else}<span>—</span>{/each}</div>{#if l?.canonical_source_ref?.kind==='chronicle'}<button on:click={()=>openCanonical(l.canonical_source_ref)}>查看地点来源</button>{/if}<h4>最近 Events</h4>{#each locationEvents(selectedLocation).slice(0,5) as e}<button class="wh-event-link" on:click={()=>openEvent(e)}>{dateLabel(e)} · {e.title}</button>{/each}<button on:click={()=>filterLocation(selectedLocation)}>在 Timeline 查看</button><button on:click={()=>{setScope('locationId',selectedLocation);navigate('threads')}}>筛选 Threads</button><button on:click={()=>{setScope('locationId',selectedLocation);navigate('graph')}}>在 Graph 查看</button>{#each l?.thread_ids||[] as id}<button class="wh-event-link" on:click={()=>navigate('thread',id)}>{threadName(id)}</button>{/each}{:else if homeThread&&page==='threads'}<div class="wh-visual-inspector"><small>VISUAL INSPECTOR</small><h3>{homeThread.title}</h3><p class="wh-inspector-state">{homeThread.current_state?.text||homeThread.current_state_excerpt||'Chronicle 暂无 Current State 记录。'}</p><div class="wh-inspector-switch" aria-label="Thread 投影">{#each ['Time','Graph','Map'] as projection}<button class:active={inspectorProjection===projection} on:click={()=>inspectorProjection=projection}>{projection}</button>{/each}</div><ThreadProjection thread={homeThread} {repository} projection={inspectorProjection} openEvent={e=>{navigate('thread',homeThread.thread_id,{eventId:e.event_id});threadProjection='Timeline'}} openEntity={id=>navigate('entity',id)} openLocation={id=>{setScope('locationId',id);navigate('map')}}/><h4>Open Questions · {homeThread.open_question_count}</h4>{#each homeThread.open_questions?.filter(q=>q.state==='open').slice(0,3)||[] as question}<div class="wh-question-preview">○ {question.question}</div>{:else}<p class="wh-muted">没有未解问题。</p>{/each}<h4>Latest material change</h4><p>{formatDate(homeThread.last_meaningful_change_at)} · {homeThread.latest_event_summary||'暂无 Event'}</p><button class="wh-primary-action" on:click={()=>navigate('thread',homeThread.thread_id)}>打开 Thread →</button><button disabled={!homeThread.canonical_ref.obsidian_path} on:click={()=>openRef(homeThread.canonical_ref)}>打开源笔记</button></div>{:else if inspectedEvent}<h3>{inspectedEvent.title}</h3><p>{inspectedEvent.summary}</p><p>{dateLabel(inspectedEvent)}</p><p>置信度 {inspectedEvent.confidence} · {inspectedEvent.claim_count} Claims · {inspectedEvent.source_count} Sources</p><button on:click={()=>openEvent(inspectedEvent)}>在 Thread 中打开</button>{#if inspectedEvent.location_ids?.length}<button on:click={()=>showEventMap(inspectedEvent)}>在 Map 高亮地点</button>{/if}<button on:click={()=>focusGraph('event:'+inspectedEvent.event_id)}>在 Graph 高亮 Event</button>{:else if inspectedEntity}<h3>{inspectedEntity.name}</h3><p>{inspectedEntity.kind} · {inspectedEntity.thread_count} Threads · {inspectedEntity.event_count} Events</p><button on:click={()=>navigate('entity',inspectedEntity.entity_id)}>打开 Entity</button>{/if}</aside>{/if}
  </main>
  <footer class="wh-footer">Schema {repository.manifest.schema_version} · Generator {repository.manifest.generator_version} · Source {repository.manifest.source_revision}</footer>
  {/if}
</div>
